raw_sql:
SELECT AVG(cost_usd) AS average_cost_usd
FROM marts.fct_requests
WHERE model = 'local';

SELECT COUNT(*) AS total_escalations
FROM support.tickets
WHERE status = 'Escalated';

SELECT COUNT(*) AS recent_tickets
FROM support.tickets
WHERE opened_at >= NOW() - INTERVAL '1 day';

SELECT hourly_cost_usd
FROM support.agents
WHERE display_name = 'Farhana Khan';

SELECT AVG(input_tokens + output_tokens) AS avg_total_tokens
FROM marts.fct_requests
WHERE split = 'test';

SELECT email
FROM support.agents
WHERE is_active = true;

SELECT email
FROM support.agents
WHERE display_name = 'Nadia Ahmed';

SELECT COUNT(*) AS decision_count
FROM marts.fct_outcomes
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';

SELECT monthly_budget_usd
FROM marts.dim_tenant
WHERE tenant_id = (SELECT tenant_id FROM marts.fct_requests WHERE run_id = 'your_run_id' LIMIT 1);

SELECT COUNT(*) AS model_calls_from_cache
FROM marts.fct_requests
WHERE cache_status = 'HIT';

SELECT COUNT(*) AS high_priority_tickets
FROM support.tickets
WHERE tenant_id = 'support' AND priority = 'high';

SELECT COUNT(*) 
FROM support.agents 
WHERE team = 'billing';

SELECT COUNT(*) AS tfidf_baseline_decisions
FROM marts.fct_outcomes
WHERE prompt_version = 'tf-idf-baseline' AND split = 'tune';

SELECT COUNT(DISTINCT gold_category) AS distinct_gold_intents
FROM marts.fct_outcomes
WHERE split = 'test';

SELECT COUNT(*) AS chat_channel_tickets
FROM support.tickets
WHERE channel = 'chat' AND status = 'billing-tenant';

SELECT SUM(output_tokens) AS total_output_tokens
FROM marts.fct_requests
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';

SELECT COUNT(*) AS open_tickets
FROM support.tickets
WHERE tenant_id = 'support' AND status = 'open';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT COUNT(*) 
FROM support.agents 
WHERE hourly_cost_usd > 6;

SELECT COUNT(*) AS resolved_tickets
FROM support.tickets
WHERE status = 'resolved';

SELECT COUNT(*) AS current_headcount
FROM support.agents
WHERE is_active = true;

SELECT accuracy
FROM marts.mart_cost_per_outcome
WHERE feature = 'local_model';

SELECT COUNT(*) AS reopened_tickets
FROM support.tickets
WHERE status = 'Reopened';
